input.query:
(
  $p := payload;
  $m := mapping;
  $get := function($o,$path){ $reduce($split($path,"."),function($v,$k){$lookup($v,$k)},$o) };
  $configured := $type($m) = "object" and $type($m.idPath) = "string" and $length($m.idPath) > 0 and $type($m.lineItemsPath) = "string" and $length($m.lineItemsPath) > 0 and $type($m.orderColumns) = "array" and $count($m.orderColumns) > 0 and $type($m.lineColumns) = "array" and $count($m.lineColumns) > 0;
  $id := $configured ? $get($p,$m.idPath) : null;
  $items := $configured ? $get($p,$m.lineItemsPath) : null;
  $validId := $type($id) = "string" ? $length($trim($id)) > 0 : ($type($id) = "number" ? ($floor($id) = $id and $abs($id) <= 9007199254740991) : false);
  $valid := $configured and $validId and $type($items) = "array" and $count($items) > 0;
  $orderId := $validId ? ($type($id) = "string" ? $trim($id) : $string($id)) : "";
  $cell := function($column,$item){(
    $value := $column.source = "order_id" ? $orderId : ($column.source = "order" ? $get($p,$column.path) : ($column.source = "item" ? $get($item,$column.path) : null));
    $exists($value) and $value != null ? $value : ""
  )};
  $orderRows := $valid ? [$map($m.orderColumns,function($c){$cell($c,null)})] : [];
  $lineRows := $valid ? $reduce($items,function($rows,$item){$append($rows,[$map($m.lineColumns,function($c){$cell($c,$item)})])},[]) : [];
  {"valid":$valid,"status":$configured ? ($valid ? "ready" : "rejected") : "setup_required","orderId":$orderId,"orderRows":$orderRows,"lineRows":$lineRows,"issues":$configured ? ($valid ? [] : ["Order must have a nonempty stable ID and a nonempty line-item array; no rows were dispatched."]) : ["Setup required: mapping.idPath, mapping.lineItemsPath, mapping.orderColumns and mapping.lineColumns. Column descriptors use source order_id, order or item and a dot-separated path. Include order_id in both tabs; map customer and shipping fields as order paths. Missing optional fields become empty cells. Configure the webhook request_id_field to the same ID path."]}
)
